{
  "name": "串口通信助手组件",
  "name_en": "Serial Device Communication Helper",
  "manufacturer": "",
  "description": "这是一个非实体的软件组件，用于在实验系统中统一管理串口连接。它提供串口名标准化、打开与关闭端口、读写数据包、按终止符读取、缓冲区清理以及端口参数查询等功能，便于各类基于串口通信的实验仪器接入。",
  "description_en": "This is a non-physical software component used to standardize serial communication in a lab system. It provides port-name normalization, port open/close control, packet read/write, terminator-based reads, buffer clearing, and serial parameter queries, helping integrate various serial-connected laboratory instruments.",
  "actions": [
    {
      "action_name": "auto-normalizePortName",
      "description": "标准化串口名称",
      "description_en": "Normalize a serial port name"
    },
    {
      "action_name": "auto-open",
      "description": "打开串口连接",
      "description_en": "Open a serial port connection"
    },
    {
      "action_name": "auto-close",
      "description": "关闭串口连接",
      "description_en": "Close the serial port connection"
    },
    {
      "action_name": "auto-readAll",
      "description": "读取缓冲区中全部可用字节",
      "description_en": "Read all available bytes from the serial buffer"
    },
    {
      "action_name": "auto-write",
      "description": "向串口写入数据",
      "description_en": "Write data to the serial port"
    },
    {
      "action_name": "auto-read",
      "description": "按指定长度从串口读取数据，可检查终止符",
      "description_en": "Read a specified number of bytes from the serial port, optionally checking a terminator"
    },
    {
      "action_name": "auto-readUntil",
      "description": "持续读取直到收到终止符",
      "description_en": "Read until a terminator is received"
    },
    {
      "action_name": "auto-readline",
      "description": "按行从串口读取数据",
      "description_en": "Read a line of data from the serial port"
    },
    {
      "action_name": "auto-hasDataToRead",
      "description": "检查串口是否有待读数据",
      "description_en": "Check whether the serial port has data waiting to be read"
    },
    {
      "action_name": "auto-clearBuffer",
      "description": "清空串口缓冲区",
      "description_en": "Clear the serial buffer"
    },
    {
      "action_name": "auto-getPort",
      "description": "获取当前配置的串口",
      "description_en": "Get the currently configured serial port"
    },
    {
      "action_name": "auto-getBaudrate",
      "description": "获取当前配置的波特率",
      "description_en": "Get the configured baud rate"
    }
  ],
  "tag_hints": [
    "serial communication",
    "RS-232",
    "USB serial",
    "packet I/O",
    "buffer management",
    "lab automation software",
    "port configuration"
  ]
}

